using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Uses constructor injection — the SDK resolves HttpClient and ILogger
/// automatically because they are registered in DI, and they never appear
/// in the tool's JSON schema sent to the LLM.
/// </summary>
[McpServerToolType]
public class JsonPlaceholderTools(HttpClient httpClient, ILogger<JsonPlaceholderTools> logger)
{
    [McpServerTool(ReadOnly = true), Description("Get a post by its numeric ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The numeric ID of the post (1-100).")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {PostId}", postId);
        var post = await httpClient.GetFromJsonAsync<Post>(
            $"posts/{postId}", cancellationToken);
        return $"[{post!.Id}] {post.Title}\n\n{post.Body}";
    }

    [McpServerTool(ReadOnly = true), Description("List posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Optional user ID to filter posts by author.")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = userId.HasValue ? $"posts?userId={userId}" : "posts";
        logger.LogInformation("Listing posts: {Url}", url);
        var posts = await httpClient.GetFromJsonAsync<Post[]>(url, cancellationToken);
        return string.Join("\n", posts!.Select(p => $"[{p.Id}] {p.Title}"));
    }

    [McpServerTool, Description("Create a new post via the REST API.")]
    public async Task<string> CreatePost(
        [Description("Title of the new post.")] string title,
        [Description("Body content of the new post.")] string body,
        [Description("Author user ID.")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);
        var response = await httpClient.PostAsJsonAsync("posts",
            new { title, body, userId }, cancellationToken);
        response.EnsureSuccessStatusCode();
        var created = await response.Content.ReadFromJsonAsync<Post>(cancellationToken);
        return $"Created post with ID {created!.Id}";
    }
}

public record Post
{
    [JsonPropertyName("id")]
    public int Id { get; init; }

    [JsonPropertyName("userId")]
    public int UserId { get; init; }

    [JsonPropertyName("title")]
    public string Title { get; init; } = "";

    [JsonPropertyName("body")]
    public string Body { get; init; } = "";
}

